IF NOT EXISTS(select 1 from [INFORMATION_SCHEMA].[TABLES] where TABLE_SCHEMA = 'integration' and TABLE_NAME = 'AssetFieldRelationship') begin CREATE TABLE [integration].[AssetFieldRelationship] ( [Uid] uniqueidentifier constraint DF_IntegrationAssetFieldRelationship_Uid default(newid()) not null, [SynchedAssetTypeID] int NOT NULL, [SourceID] varchar(100) NOT NULL, [FieldName] nvarchar(250) NOT NULL, [AssetSourceType] varchar(100) NOT NULL, [AssetSourceID] varchar(100) NOT NULL, IsSubject bit NOT NULL, IntersectTypeID int NULL, SubjectID bigint NULL, ObjectID bigint NULL, IntersectID int NULL, Present bit constraint DF_IntegrationAssetFieldRelationship_Present default(0) NOT NULL, [Action] varchar(1) NULL, CONSTRAINT [PK_IntegrationAssetFieldRelationship] PRIMARY KEY NONCLUSTERED ( [Uid] ASC ) );
create clustered index CX_IntegrationAssetFieldRelationship on [integration].[AssetFieldRelationship] (SynchedAssetTypeID, SourceID, FieldName, AssetSourceType, AssetSourceID);
end
